class Solution {
public:
    int memo[129][64][64];
    int R, C, catJump, mouseJump;
    int food, catPos, mousePos;
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};
    vector<string> g;

    bool dp(int turn, int m_pos, int c_pos) {
        if (turn >= 128) return false;
        if (m_pos == c_pos) return false;
        if (c_pos == food) return false;
        if (m_pos == food) return true;
        if (memo[turn][m_pos][c_pos] != -1) return memo[turn][m_pos][c_pos];
        int mr = m_pos / C, mc = m_pos % C;
        int cr = c_pos / C, cc = c_pos % C;
        if (turn % 2 == 0) {
            if (dp(turn + 1, m_pos, c_pos)) return memo[turn][m_pos][c_pos] = 1;
            for (int d = 0; d < 4; d++) {
                for (int j = 1; j <= mouseJump; j++) {
                    int nr = mr + dr[d] * j, nc = mc + dc[d] * j;
                    if (nr < 0 || nr >= R || nc < 0 || nc >= C || g[nr][nc] == '#') break;
                    if (dp(turn + 1, nr * C + nc, c_pos)) return memo[turn][m_pos][c_pos] = 1;
                }
            }
            return memo[turn][m_pos][c_pos] = 0;
        } else {
            if (!dp(turn + 1, m_pos, c_pos)) return memo[turn][m_pos][c_pos] = 0;
            for (int d = 0; d < 4; d++) {
                for (int j = 1; j <= catJump; j++) {
                    int nr = cr + dr[d] * j, nc = cc + dc[d] * j;
                    if (nr < 0 || nr >= R || nc < 0 || nc >= C || g[nr][nc] == '#') break;
                    if (!dp(turn + 1, m_pos, nr * C + nc)) return memo[turn][m_pos][c_pos] = 0;
                }
            }
            return memo[turn][m_pos][c_pos] = 1;
        }
    }
    bool canMouseWin(vector<string>& grid, int cj, int mj) {
        g = grid;
        R = grid.size(); C = grid[0].size();
        catJump = cj; mouseJump = mj;
        memset(memo, -1, sizeof(memo));
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (grid[r][c] == 'F') food = r * C + c;
                else if (grid[r][c] == 'C') catPos = r * C + c;
