class Solution {
    private int[][][] memo;
    private int R, C, catJump, mouseJump, food;
    private int[] dr = {-1, 1, 0, 0};
    private int[] dc = {0, 0, -1, 1};
    private String[] g;

    private boolean dp(int turn, int m_pos, int c_pos) {
        if (turn >= 128) return false;
        if (m_pos == c_pos) return false;
        if (c_pos == food) return false;
        if (m_pos == food) return true;
        if (memo[turn][m_pos][c_pos] != -1) return memo[turn][m_pos][c_pos] == 1;
        int mr = m_pos / C, mc = m_pos % C;
        int cr = c_pos / C, cc = c_pos % C;
        if (turn % 2 == 0) {
            if (dp(turn + 1, m_pos, c_pos)) {
                memo[turn][m_pos][c_pos] = 1;
                return true;
            }
            for (int d = 0; d < 4; d++) {
                for (int j = 1; j <= mouseJump; j++) {
                    int nr = mr + dr[d] * j, nc = mc + dc[d] * j;
                    if (nr < 0 || nr >= R || nc < 0 || nc >= C || g[nr].charAt(nc) == '#') break;
                    if (dp(turn + 1, nr * C + nc, c_pos)) {
                        memo[turn][m_pos][c_pos] = 1;
                        return true;
                    }
                }
            }
            memo[turn][m_pos][c_pos] = 0;
            return false;
        } else {
            if (!dp(turn + 1, m_pos, c_pos)) {
                memo[turn][m_pos][c_pos] = 0;
                return false;
            }
            for (int d = 0; d < 4; d++) {
                for (int j = 1; j <= catJump; j++) {
                    int nr = cr + dr[d] * j, nc = cc + dc[d] * j;
                    if (nr < 0 || nr >= R || nc < 0 || nc >= C || g[nr].charAt(nc) == '#') break;
                    if (!dp(turn + 1, m_pos, nr * C + nc)) {
                        memo[turn][m_pos][c_pos] = 0;
                        return false;
                    }
                }
            }
            memo[turn][m_pos][c_pos] = 1;
            return true;
        }
    }
    public boolean canMouseWin(String[] grid, int cj, int mj) {
        g = grid;
        R = grid.length; C = grid[0].length();
        catJump = cj; mouseJump = mj;
        memo = new int[129][64][64];
        for (int i = 0; i < 129; i++) {
            for (int j = 0; j < 64; j++) Arrays.fill(memo[i][j], -1);
        }
        int mousePos = 0, catPos = 0;
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                char ch = grid[r].charAt(c);
                if (ch == 'F') food = r * C + c;
                else if (ch == 'C') catPos = r * C + c;
                else if (ch == 'M') mousePos = r * C + c;
            }
        }
        return dp(0, mousePos, catPos);
    }
}

var canMouseWin = function(grid, catJump, mouseJump) {
    const R = grid.length, C = grid[0].length;
    let food = 0, catPos = 0, mousePos = 0;
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            const ch = grid[r][c];
            if (ch === 'F') food = r * C + c;
            else if (ch === 'C') catPos = r * C + c;
            else if (ch === 'M') mousePos = r * C + c;
        }
    }
    const memo = new Map();
    const dr = [-1, 1, 0, 0], dc = [0, 0, -1, 1];
    function dp(turn, m_pos, c_pos) {
        if (turn >= 128) return false;
        if (m_pos === c_pos) return false;
        if (c_pos === food) return false;
        if (m_pos === food) return true;
        const key = (turn << 12) | (m_pos << 6) | c_pos;
        if (memo.has(key)) return memo.get(key);
        const mr = Math.floor(m_pos / C), mc = m_pos % C;
        const cr = Math.floor(c_pos / C), cc = c_pos % C;
        if (turn % 2 === 0) {
            if (dp(turn + 1, m_pos, c_pos)) {
                memo.set(key, true);
                return true;
            }
            for (let d = 0; d < 4; d++) {
                for (let j = 1; j <= mouseJump; j++) {
                    const nr = mr + dr[d] * j, nc = mc + dc[d] * j;
                    if (nr < 0 || nr >= R || nc < 0 || nc >= C || grid[nr][nc] === '#') break;
                    if (dp(turn + 1, nr * C + nc, c_pos)) {
                        memo.set(key, true);
                        return true;
                    }
                }
            }
            memo.set(key, false);
            return false;
        } else {
            if (!dp(turn + 1, m_pos, c_pos)) {
                memo.set(key, false);
                return false;
            }
            for (let d = 0; d < 4; d++) {
                for (let j = 1; j <= catJump; j++) {
                    const nr = cr + dr[d] * j, nc = cc + dc[d] * j;
                    if (nr < 0 || nr >= R || nc < 0 || nc >= C || grid[nr][nc] === '#') break;
                    if (!dp(turn + 1, m_pos, nr * C + nc)) {
                        memo.set(key, false);
                        return false;
                    }
                }
            }
            memo.set(key, true);
            return true;
        }
    }
    return dp(0, mousePos, catPos);
};
